/**
 * 一条诊断结论。
 * 
 * 每项都带**数据来源**和**观测时间**，对应 spec「每个结论展示数据来源、
 * 检测时间和判断依据，避免只给一个不可解释的分数」。
 */
export type DiagnosticItem = { 
/**
 * 稳定标识，前端据此做差异对比
 */
id: string; 
/**
 * 展示名
 */
label: string; 
/**
 * 采集状态
 */
evidence: EvidenceStatus; 
/**
 * 解释状态（必须由 `Verdict::from_evidence` 得出）
 */
verdict: Verdict; 
/**
 * 观测到的值；未观测到时为 None（**不要**用空串冒充成功）
 */
value: string | null; 
/**
 * 判断依据 / 补充说明
 */
detail: string | null; 
/**
 * 数据来源，例如 "本机路由表"、"系统 DNS 配置"
 */
source: string; 
/**
 * 观测时间 RFC3339
 */
observedAt: string; 
/**
 * 失败时的分类
 */
failure: FailureKind | null; 
/**
 * 并排对照（一致性类结论用）。有它时界面优先渲染成 `左 ↔ 右`。
 */
comparison: Comparison | null; 
/**
 * **一句话的可核对事实**，例如「IPv6 可独立出网（2a12:...）」。
 * 
 * 与 `detail` 的分工很重要：`evidence_note` 是「观测到了什么」，
 * 短、具体、能直接拿去核对；`detail` 是「这意味着什么、下一步怎么办」，
 * 属于解释，放 hover 即可。参考项目的做法就是把
 * 「网页可获取额外公网地址（183.67.52.5）」这种具体值放在正文，
 * 而不是一段"这通常说明……"的推断。
 */
evidenceNote: string | null }
